const menu=document.querySelector('.menu'),nav=document.querySelector('nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);nav.classList.toggle('open',open);menu.textContent=open?'Chiudi −':'Menu +';});
nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu +';}));
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const targets=document.querySelectorAll('.section-heading,.project,.timeline article,.journey>div:first-child');
if('IntersectionObserver' in window&&!reduced){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target);}}),{threshold:.12});targets.forEach(t=>{t.classList.add('reveal');observer.observe(t);});}
let queued=false;addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(()=>{const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max>0?scrollY/max*100:0)+'%';queued=false;});}},{passive:true});
const light=document.querySelector('#light');light.addEventListener('input',()=>{document.querySelector('#light-value').textContent=light.value+'%';const study=document.querySelector('.light-study');study.style.setProperty('--light',light.value+'%');study.style.setProperty('--angle',(45+Number(light.value)*1.3)+'deg');study.style.setProperty('--shadow',(50-Number(light.value))+'px');});
const dialog=document.querySelector('dialog'),tabs=[...document.querySelectorAll('[role=tab]')];const content={Concept:'Qui troverai il tema, la domanda progettuale e le intenzioni del progetto. Testo da ricavare dal portfolio originale.',Processo:'Qui troverai schizzi, prove, modelli e passaggi di sviluppo. Materiali da selezionare dal portfolio originale.',Esito:'Qui troverai immagini finali, dettagli e crediti verificati. Gli studi grafici della homepage non rappresentano questo progetto.'};
function selectTab(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;});document.querySelector('#project-panel').textContent=content[tab.dataset.tab];document.querySelector('#project-panel').setAttribute('aria-labelledby',tab.id);}
document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#dialog-title').textContent=['Compluvio','Soundplace'][b.dataset.project];selectTab(tabs[0]);dialog.showModal();}));
tabs.forEach((t,i)=>{t.addEventListener('click',()=>selectTab(t));t.addEventListener('keydown',e=>{let index;if(e.key==='ArrowRight')index=(i+1)%tabs.length;if(e.key==='ArrowLeft')index=(i+tabs.length-1)%tabs.length;if(e.key==='Home')index=0;if(e.key==='End')index=tabs.length-1;if(index!==undefined){e.preventDefault();selectTab(tabs[index]);tabs[index].focus();}});});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.querySelector('#contact-info').addEventListener('click',()=>document.querySelector('#contact-status').textContent='Email e profili pubblici sono in attesa di conferma. Nessun messaggio viene inviato da questa anteprima.');
